/* Compare deferred occlusion with the exact same commands executed unculled. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../engine/native/knlcore.c"
static unsigned seed=87;static unsigned rnd(void){seed=seed*1664525+1013904223;return seed;}
static float rf(float low,float high){return low+(high-low)*(rnd()%10001)/10000.f;}
static void reference(CmdList *L){g_sprite_clip_bottom=-1;for(int k=0;k<L->n;k++){Cmd*c=&L->c[k];float*f=c->f;switch(c->op){case C_CLEAR:do_clear(c->u[0]);break;case C_DRAW:do_draw(c->t,f[0],f[1],f[2],f[3],f[4],f[5],c->u[0],c->i[0]);break;case C_LIT:do_draw_lit(c->t,f[0],f[1],f[2],f[3],f[4],f[5],c->u[0],c->i,c->i+12,c->u[1],c->u[2],c->i[15]);break;case C_GRAD:do_quad_gradient(f[0],f[1],f[2],f[3],c->u[0],c->u[1],c->u[2],c->u[3],c->i[0]);break;case C_REFLECT:do_reflect(c->i[0],c->i[1],f[0],c->u[0],f[1],f[2]);break;}}}
static void fill(Cmd*c,int kind){memset(c,0,sizeof(*c));c->op=C_GRAD;c->f[0]=0;c->f[1]=rf(0,40);c->f[2]=64;c->f[3]=48;c->u[0]=c->u[1]=rnd()|0xff000000;c->u[2]=c->u[3]=rnd()|0xff000000;switch(kind){case 1:c->u[0]=c->u[1]&=0x7fffffff;break;case 2:c->i[0]=1;break;case 3:c->f[0]=1;break;case 4:c->f[2]=63;break;case 5:c->f[3]=47;break;case 6:c->u[2]=c->u[3]&=0x7fffffff;break;case 7:c->f[1]=0;break;case 8:c->f[0]=-20;c->f[2]=90;c->f[3]=60;break;}}
int main(void){if(knl_init(64,48,1,0))return 2;for(int n=0;n<2;n++){uint32_t*px=malloc(16*16*4);for(int i=0;i<256;i++)px[i]=rnd();int t=add_tex(16,16,px);if(n){Tex*T=&g_tex[t];T->pal=malloc(1024);memcpy(T->pal,px,1024);T->idx=malloc(256);for(int i=0;i<256;i++)T->idx[i]=i;free(T->px);T->px=NULL;}}
 uint32_t baseline[64*48];int proved=0;
 for(int n=0;n<1000;n++){Cmd cmds[31];memset(cmds,0,sizeof(cmds));cmds[0].op=C_CLEAR;cmds[0].u[0]=0xff102030;for(int j=1;j<31;j++){Cmd*c=&cmds[j];c->op=(rnd()&1)?C_DRAW:C_LIT;c->t=rnd()%2;c->f[0]=rf(-3,3);c->f[1]=(rnd()%3)?0:rf(-1,1);c->f[2]=(rnd()%3)?0:rf(-1,1);c->f[3]=rf(-3,3);c->f[4]=rf(-20,70);c->f[5]=rf(-20,50);c->u[0]=rnd();c->u[1]=rnd();c->u[2]=rnd();for(int z=0;z<12;z++)c->i[z]=rnd()%400;c->i[12]=3;c->i[13]=7;c->i[14]=11;c->i[15]=rnd()%4;}
 int kind=n%9,at=3+rnd()%24;fill(&cmds[at],kind);if(n%5==0)fill(&cmds[1],0);if(n%4==0){Cmd*c=&cmds[2];memset(c,0,sizeof(*c));c->op=C_REFLECT;c->i[0]=1+rnd()%46;c->i[1]=48;c->f[0]=.8;c->f[1]=1;c->f[2]=1.2;c->u[0]=0x80403020;}
 CmdList list={cmds,31,31};int bound;int occ=bottom_occluder(&list,&bound);if(n%5!=0){int valid=kind==0||kind==7||kind==8;if((occ>=0)!=valid){fprintf(stderr,"bad occluder gate %d\n",kind);return 1;}}
 g_stats_pixels=0;reference(&list);int before=g_stats_pixels;memcpy(baseline,g_fb,sizeof(baseline));g_stats_pixels=0;run_list(&list);if(memcmp(baseline,g_fb,sizeof(baseline))){fprintf(stderr,"pixel mismatch sample %d kind %d occ%d bottom%d at%d\n",n,kind,occ,bound,at);for(int z=0;z<64*48;z++)if(baseline[z]!=g_fb[z]){fprintf(stderr,"first mismatch x%d y%d baseline%08x actual%08x\n",z%64,z/64,baseline[z],g_fb[z]);break;}for(int z=0;z<31;z++)if(cmds[z].op==C_GRAD||cmds[z].op==C_REFLECT)fprintf(stderr,"cmd%d op%d xy %f %f %f %f i%d\n",z,cmds[z].op,cmds[z].f[0],cmds[z].f[1],cmds[z].f[2],cmds[z].f[3],cmds[z].i[0]);return 1;}if(occ<0&&g_stats_pixels!=before){fprintf(stderr,"fallback changed raster work\n");return 1;}if(g_sprite_clip_bottom!=-1){fprintf(stderr,"clip state leaked\n");return 1;}if(g_stats_pixels<before)proved++;}
 if(proved<100){fprintf(stderr,"did not exercise hidden pixel removal: %d\n",proved);return 1;}printf("PASS: 1000 opaque-fill/alpha/additive/coverage/rotated-lit/indexed/foreground/reflection comparisons; hidden work reduced in %d cases\n",proved);knl_shutdown();return 0;}
